                    let b1 = *in_0.add(1);
                    in_0 = in_0.add(2);
                    hold = hold.wrapping_add((b0 as c_ulong) << bits);
                    bits = bits.wrapping_add(8);
                    hold = hold.wrapping_add((b1 as c_ulong) << bits);
                    bits = bits.wrapping_add(8);
